export async function api<T=any>(path:string,body?:any):Promise<T>{const r=await fetch(path,{method:body?"POST":"GET",headers:body?{"Content-Type":"application/json"}:undefined,body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok)throw new Error(j.message||j.error||"API error");return j}
export const EazyAPI={scanPantry:(images:string[])=>api("/api/pantry/scan",{images}),createMealPlan:(input:any)=>api("/api/meal-plan",input),videoRecipe:(videoUrl:string)=>api("/api/recipe/from-video",{videoUrl}),videoStatus:(id:string)=>api("/api/recipe/from-video/status?id="+encodeURIComponent(id)),mealImage:(title:string)=>api("/api/meal-image",{title}),cookPlan:(meal:any,people:number)=>api("/api/cook-plan",{title:meal.title,ingredients:meal.ingredients||[],people})};
